		const name = e && typeof e.name === 'string' ? e.name.trim() : '';
		if (!name || name.length > 60 || /[,;]/.test(name)) { fehler.push(`${p}.name: 1–60 Zeichen, ohne Komma/Semikolon`); continue; }
