 */
function nachrichtFreigeber({ vorgang, freigabe, fehlende, link: url, ablaufText, art, anlass, kontext_html: kontext }) {
	const liste = (fehlende || []).map((f) => `<li>${esc(f.anzeigename)}</li>`).join('');
