const MAX_LAENGE = 4096;
const ERLAUBT = { b: 'b', strong: 'b', i: 'i', em: 'i', u: 'u', s: 's', code: 'code', pre: 'pre' };
const BENANNT = { nbsp: ' ', amp: '&amp;', lt: '&lt;', gt: '&gt;', quot: '&quot;', apos: '&#39;' };

function escapeText(s) {
